public Payment(Order order, java.math.BigDecimal capturedAmount) {
    super();
    this.order = order;
    this.capturedAmount = capturedAmount;
    this.refundedAmount = java.math.BigDecimal.ZERO;
}

public Order(java.math.BigDecimal total) {
    super();
    this.total = total;
}

public static void main(java.lang.String[] args) {
    Customer customer = new Customer();
    Order order = new Order(new java.math.BigDecimal("100.00"));
    customer.addOrder(order);
    Payment payment = new Payment(order, new java.math.BigDecimal("80.00"));
    payment.capture();
    java.lang.System.out.println("=== Payment demonstration ===");
    java.lang.System.out.println("Order total: €" + order.getTotal());
    java.lang.System.out.println("Captured amount: €" + payment.getCapturedAmount());
    // Calculate refundable amount
    java.math.BigDecimal refundable = order.calculateRefundableAmount(payment);
    java.lang.System.out.println("Refundable amount: €" + refundable);
    // Refund €30
    payment.refund(new java.math.BigDecimal("30.00"));
    java.lang.System.out.println("\nAfter refunding €30:");
    java.lang.System.out.println("Already refunded: €" + payment.getRefundedAmount());
    refundable = order.calculateRefundableAmount(payment);
    java.lang.System.out.println("Remaining refundable amount: €" + refundable);
    // Refund the remaining amount
    payment.refund(refundable);
    java.lang.System.out.println("\nAfter refunding the remainder:");
    java.lang.System.out.println("Already refunded: €" + payment.getRefundedAmount());
    refundable = order.calculateRefundableAmount(payment);
    java.lang.System.out.println("Remaining refundable amount: €" + refundable);
}

public void refund(java.math.BigDecimal amount) {
    java.math.BigDecimal refundable = this.order.calculateRefundableAmount(this);
    if ((amount.compareTo(java.math.BigDecimal.ZERO) < 0) || (amount.compareTo(refundable) > 0)) {
        throw new java.lang.IllegalArgumentException("Invalid refund amount");
    }
    this.refundedAmount = this.refundedAmount.add(amount);
}

// Calculates how much of a payment can still be refunded
public java.math.BigDecimal calculateRefundableAmount(Payment payment) {
    if (!payment.isCaptured()) {
        return java.math.BigDecimal.ZERO;
    }
    java.math.BigDecimal remainingPayment = payment.getCapturedAmount().subtract(payment.getRefundedAmount());
    java.math.BigDecimal remainingOrderValue = this.total.subtract(payment.getRefundedAmount());
    return remainingPayment.min(remainingOrderValue).max(java.math.BigDecimal.ZERO);
}

